sysevent_in_email_action.script:
(function runAction( /*GlideRecord*/ current, /*GlideRecord*/ event, /*EmailWrapper*/ email, /*ScopedEmailLogger*/ logger, /*EmailClassifier*/ classifier) {

	gs.info("SF*** current record inbound action "+current.sys_id);
    // Implement email action here

    checkForVerifyEmail();

    function checkForVerifyEmail() {
        var email_subject = email.subject.toLowerCase();
        if (email_subject.indexOf('i accept') >= 0) {
            current.emp_agree = 'Yes';
            current.work_notes = 'User replied with "I accept"';
			current.state = 106;
            current.update();
        }

        if (email_subject.indexOf('i decline') >= 0) {
            current.emp_agree = 'No';
            current.work_notes = 'User replied with "I decline"';
			current.state = 30;
            current.update();
        }
    }

})(current, event, email, logger, classifier);
